import type { ReactNode } from "react";

/**
 * Registry of the app's Lottie celebrations. JSON lives in /public/lottie
 * (generated by scripts/generate-lottie.mjs — see public/lottie/LICENSES.md)
 * and each entry has a static SVG fallback for reduced motion / slow loads.
 */
export type LottieKey = "milestone-star" | "growth-sparkle" | "confetti-soft";

export const LOTTIE: Record<LottieKey, { src: string; fallback: ReactNode }> = {
  "milestone-star": {
    src: "/lottie/milestone-star.json",
    fallback: <StaticStar />,
  },
  "growth-sparkle": {
    src: "/lottie/growth-sparkle.json",
    fallback: <StaticSparkles />,
  },
  "confetti-soft": {
    src: "/lottie/confetti-soft.json",
    fallback: null,
  },
};

function StaticStar() {
  return (
    <svg viewBox="0 0 200 200" className="h-full w-full" aria-hidden>
      <path
        d="M100 38 l17 37 41 5 -30 28 8 40 -36 -20 -36 20 8 -40 -30 -28 41 -5 z"
        fill="oklch(0.86 0.14 88)"
        stroke="oklch(0.74 0.14 75)"
        strokeWidth="5"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function StaticSparkles() {
  const sparkle = "M0 -14 C 2 -2 2 -2 14 0 C 2 2 2 2 0 14 C -2 2 -2 2 -14 0 C -2 -2 -2 -2 0 -14 z";
  return (
    <svg viewBox="0 0 200 200" className="h-full w-full" aria-hidden>
      <path d={sparkle} transform="translate(60 70) scale(1.4)" fill="oklch(0.86 0.12 88)" />
      <path d={sparkle} transform="translate(140 60)" fill="oklch(0.82 0.08 200)" />
      <path d={sparkle} transform="translate(120 140) scale(1.1)" fill="oklch(0.84 0.08 15)" />
    </svg>
  );
}
